import clsx from 'clsx';
import './AcidStepList.css';

export interface StepItem {
    id: string;
    label: string;
}

export interface AcidStepListProps {
    steps: StepItem[];
    activeId?: string;
    className?: string;
}

export const AcidStepList = ({ steps, activeId, className }: AcidStepListProps) => {
    return (
        <ul className={clsx('ac-step-list', className)}>
            {steps.map((item, idx) => {
                const isActive = activeId === item.id;
                const number = (idx + 1).toString().padStart(2, '0');
                return (
                    <li key={item.id} className={clsx('ac-step-item', isActive && 'ac-step-active')}>
                        <span className="ac-step-num">{number}</span>
                        <span className="ac-step-label">{item.label}</span>
                    </li>
                );
            })}
        </ul>
    );
};

.ac-step-list {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.ac-step-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-family: var(--font-mono);
    font-size: 0.8rem;
    letter-spacing: 0.05em;
    color: var(--ac-text-secondary);
    cursor: default;
    transition: color 0.2s;
}

.ac-step-active {
    color: var(--ac-text-primary);
}

.ac-step-item:hover {
    color: var(--ac-text-primary);
}

.ac-step-num {
    color: var(--ac-brand);
    /* Orange highlight for numbers */
}

/* If active, keep orange, others could be muted if we wanted, but let's keep it uniform */
